    async def re_execute_task_result(
        self,
        task_id: str,
        *,
        parameter_overrides: typing.Optional[typing.Dict[str, typing.Optional[typing.Dict[str, typing.Any]]]] = OMIT,
        update_params: typing.Optional[bool] = OMIT,
        reconfigure: typing.Optional[bool] = OMIT,
        calibration_session_id: typing.Optional[str] = OMIT,
        idempotency_key: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ExecuteFlowResponse:
        """
        Re-execute a single task using the system single-task-executor deployment.

        Looks up the TaskResultHistoryDocument to extract task_name, qid, chip_id,
        execution_id, and tags, then delegates to FlowService to create a Prefect
        flow run via the system deployment.

        Parameters
        ----------
        task_id : str
            The task result ID to re-execute
        ctx : ProjectContext
            Project context with user and project information
        service : TaskResultService
            Injected task result service
        flow_service : FlowService
            Injected flow service

        Returns
        -------
        ExecuteFlowResponse
            Execution result with IDs and URLs

        Parameters
        ----------
        task_id : str

        parameter_overrides : typing.Optional[typing.Dict[str, typing.Optional[typing.Dict[str, typing.Any]]]]
            Optional parameter overrides: {run: {...}, input: {...}}

        update_params : typing.Optional[bool]
            Update backend parameters (e.g. qubex YAML) after execution

        reconfigure : typing.Optional[bool]
            Run Configure (system_manager load + push) before executing the task

        calibration_session_id : typing.Optional[str]
            Add the run to this calibration session (open, on the task's chip, created by the signed-in user); otherwise the request is refused before anything starts. Without it, the run joins an automatic session created for it.

        idempotency_key : typing.Optional[str]
            A retry with the same key and request returns the recorded run instead of starting another. Without a key, every request starts a new run.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ExecuteFlowResponse
            Successful Response

        Examples
        --------
        import asyncio

        from qdash.sdk._generated import AsyncQDashApi

        client = AsyncQDashApi(
            project_id="YOUR_PROJECT_ID",
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.task_result.re_execute_task_result(
                task_id="task_id",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.re_execute_task_result(
            task_id,
            parameter_overrides=parameter_overrides,
            update_params=update_params,
            reconfigure=reconfigure,
            calibration_session_id=calibration_session_id,
            idempotency_key=idempotency_key,
            request_options=request_options,
        )
        return _response.data

