    async def download_figures_as_zip(
        self,
        *,
        paths: typing.Optional[typing.Sequence[str]] = OMIT,
        filename: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> typing.AsyncIterator[bytes]:
        """
        Download multiple calibration figures as a ZIP file.

        Creates a ZIP archive on temporary storage and serves it without retaining
        the completed archive in API worker memory.

        Parameters
        ----------
        body.paths : list[str]
            List of absolute file paths to the calibration figures
        body.filename : str
            Filename for the ZIP archive (default: "figures.zip")

        Returns
        -------
        FileResponse
            ZIP archive streamed from a temporary file

        Raises
        ------
        HTTPException
            400 if no paths are provided or if any path does not exist

        Parameters
        ----------
        paths : typing.Optional[typing.Sequence[str]]

        filename : typing.Optional[str]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration. You can pass in configuration such as `chunk_size`, and more to customize the request and response.

        Returns
        -------
        typing.AsyncIterator[bytes]
            Successful Response

        Examples
        --------
        import asyncio

        from qdash.sdk._generated import AsyncQDashApi

        client = AsyncQDashApi(
            project_id="YOUR_PROJECT_ID",
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.task_result.download_figures_as_zip()


        asyncio.run(main())
        """
        async with self._raw_client.download_figures_as_zip(
            paths=paths, filename=filename, request_options=request_options
        ) as r:
            async for _chunk in r.data:
                yield _chunk
